 if(p.kind==='knob')return isTL(m)?T((/AXIS|GATE/.test(m)?'Gałka T ':'Gałka L '),(/AXIS|GATE/.test(m)?'T-knob ':'L-knob '))+m:T('Gałka ','Knob ')+n;
