 if(p.kind==='window')return T('Klamka okienna ','Window handle ')+(V11.indexOf(p.coll)>=0?n:CNAME[p.coll]);
 if(p.kind==='edge')return T('Uchwyt krawędziowy ','Edge pull ')+m;
