 if(p.kind==='knob'){return isTL(p.model)?'L '+k:(/^[SML]$/.test(k)?k:'Ø'+k).replace('Ø',/Q$/.test(p.model)?'□':'Ø');}
 if(p.kind==='door')return {PZ:T('szyld PZ','PZ escutcheon'),BB:T('szyld BB','BB escutcheon'),WC:T('szyld WC','WC escutcheon')}[k]||k;
 if(p.kind==='window')return T('komplet','set');
 if(p.kind==='edge')return 'L '+k+' mm';if(p.kind==='recess')return 'Ø'+k;if(p.kind==='plate')return {21:'21 × 34',34:'34 × 55',55:'55 × 89'}[k]||k;
 if(p.kind==='eframe')return T(['','1-krotna','2-krotna','3-krotna'][+k],['','1-gang','2-gang','3-gang'][+k]);
