 var rows=[['pull',T('Uchwyty','Pulls')],['knob',T('Gałki','Knobs')],['door',T('Klamka × rozeta drzwiowa','Lever × door rose')],['window',T('Klamka × rozeta okienna','Window handle × rose')],['esc',T('Szyldy','Escutcheons')],['other',T('Ramki, płytki, uchwyty krawędziowe i wpuszczane','Frames, covers, edge and recessed pulls')]];
