function pMaterial(){return '<section class="wrap page"><nav class="crumb" aria-label="'+T('Ścieżka','Breadcrumb')+'"><a href="#/">NOOK FORM</a> / <span>'+T('Materiał i wykończenia','Material & finishes')+'</span></nav><div class="k">CW724R</div><h1>'+T('Materiał i wykończenia','Material & finishes')+'</h1><p class="lead2">'+T('Lity, bezołowiowy mosiądz CuZn21Si3P (≤ 0,10 % Pb), zgodny z RoHS i REACH. Bez pustych korpusów, bez odlewów z cynku – ciężar czuć w dłoni.','Solid lead-free CuZn21Si3P brass (≤ 0.10 % Pb), RoHS and REACH compliant. No hollow bodies, no zinc castings – you feel the weight in your hand.')+'</p></section>'+
 '<section class="wrap pb80"><h2>'+T('Wykończenia','Finishes')+'</h2><div class="fins2">'+FILTER_FINS.map(function(f){var coated=/MB|WH|NK/.test(f);return '<div class="fin"><span class="sw big" style="background:'+FIN[f][2]+'"></span><div><h3 class="h4">'+E(T(FIN[f][0],FIN[f][1]))+' <small class="tab">'+f+'</small></h3><p>'+(coated?T('Powłoka – kolor pozostaje stały.','Coated – the colour stays.'):f==='AB-R'?T('Postarzany z reliefem: jasne pola i grzbiety, ciemne rowki – tylko na modelach z liniami, ryflami lub kratą.','Aged with relief: bright fields and ridges, dark grooves – only on models with lines, flutes or lattice.'):T('Bez powłoki – z czasem nabiera patyny tam, gdzie się go dotyka.','Uncoated – develops a patina where it is touched.'))+(/^(SB|PB|AB)$/.test(f)?' <span class="abl">'+abLine(f)+'</span>':'')+'</p></div></div>';}).join('')+'</div>'+
 '<p class="note">'+T('Wykończenia z polerowanymi akcentami (SB.PB, AB.PB) – dla kolekcji OTOCZAK, PION, OBRĄCZKA, OSIKA i KASKADA. Rant oprawy wkładów jest zawsze polerowany.','Finishes with polished accents (SB.PB, AB.PB) – for OTOCZAK, PION, OBRĄCZKA, OSIKA and KASKADA. Insert bezels are always polished.')+'</p>'+
 '<div class="g2 top mt64"><div><h2 class="h3">'+T('Wkłady','Inserts')+'</h2><p>'+T('Gałki DISC, DRUM, DIAL i STUD mają wymienny wkład w polerowanej oprawie: szkło dymione, trawertyn, bursztyn lub mosiądz. Kamień i bursztyn także jako kaboszon.','DISC, DRUM, DIAL and STUD knobs carry an exchangeable insert in a polished bezel: smoked glass, travertine, amber or brass. Stone and amber also as a cabochon.')+'</p><div class="chips">'+Object.keys(INS).map(function(k){return '<span class="tagc"><span class="sw" style="background:'+INS[k][2]+'"></span>'+T(INS[k][0],INS[k][1])+'</span>';}).join('')+'</div></div>'+
 '<div><h2 class="h3">'+T('Pielęgnacja','Care')+'</h2><p>'+T('Mosiądz bez powłoki: sucha, miękka ściereczka. Wykończenia z powłoką: wilgotna ściereczka i łagodny płyn, bez środków ściernych.','Uncoated brass: a soft dry cloth. Coated finishes: a damp cloth and mild soap, no abrasives.')+'</p><a class="lnk" href="#/info/pielegnacja">'+T('Pielęgnacja i patyna','Care & patina')+'</a></div></div>'+
 '<div class="band"><div><h2 class="h4">'+T('Zobacz wykończenia na żywo','See the finishes in person')+'</h2><p class="mut">'+T('Wyślemy płytki wykończeń i moduły do porównania.','We send finish tiles and modules to compare.')+'</p></div><a class="btn" href="#/info/probki">'+T('Zamów próbki','Order samples')+'</a></div></section>';}
