function ownRows(){return [[T('Sprzedawca','Seller'),E(OWN.company||'Mood Nook')],[T('Adres','Address'),OWN.address?E(OWN.address):''],['NIP',OWN.nip?E(OWN.nip):''],['KRS',OWN.krs?E(OWN.krs):''],['E-mail','<a href="mailto:'+MAIL+'">'+MAIL+'</a>'],[T('Telefon','Phone'),OWN.phone?'<a href="tel:'+E(OWN.phone.replace(/\s/g,''))+'">'+E(OWN.phone)+'</a>':'']];}
